"""The run's task: brief, site access, submission target, answer schema and deadline.

In a sandbox run it is read from the platform API with the run token. On a developer machine there is no
run token, and the same fields come from the scouting environment.
"""

from __future__ import annotations

import json
import os
from dataclasses import dataclass
from datetime import datetime, timezone
from typing import Any

import httpx

USER_AGENT = "day-by-day-agent/0.1"


@dataclass(frozen=True)
class SiteAccess:
    site_id: str
    url: str
    username: str
    password: str

    @property
    def credentials(self) -> dict[str, str]:
        return {"username": self.username, "password": self.password}


@dataclass(frozen=True)
class RunContext:
    brief: str
    sites: tuple[SiteAccess, ...]
    submission: dict[str, Any]
    answer_schema: dict[str, Any]
    expires_at: datetime | None

    def seconds_left(self, default: float) -> float:
        """Seconds until the run expires, or `default` when the run has no deadline (local development)."""
        if self.expires_at is None:
            return default
        return (self.expires_at - datetime.now(timezone.utc)).total_seconds()


def _parse(payload: dict[str, Any]) -> RunContext:
    sites = tuple(
        SiteAccess(
            site_id=entry["siteId"],
            url=entry["url"],
            username=entry["credentials"]["username"],
            password=entry["credentials"]["password"],
        )
        for entry in payload["access"]
    )
    expires_at = payload.get("expires_at")
    return RunContext(
        brief=payload["brief"],
        sites=sites,
        submission=payload.get("submission") or {},
        answer_schema=payload.get("answer_schema") or {},
        expires_at=datetime.fromisoformat(expires_at) if expires_at else None,
    )


def load_run_context() -> RunContext:
    api_url = os.environ.get("CHALLENGE_API_URL")
    token = os.environ.get("CHALLENGE_RUN_TOKEN")
    if api_url and token:
        response = httpx.get(
            f"{api_url.rstrip('/')}/v1/runs/current",
            headers={"x-api-key": token, "User-Agent": USER_AGENT},
            timeout=30,
        )
        response.raise_for_status()
        return _parse(response.json())

    scouting = os.environ.get("CHALLENGE_SCOUTING")
    if scouting:
        return _parse(json.loads(scouting))

    raise RuntimeError(
        "No run to work on: set CHALLENGE_API_URL and CHALLENGE_RUN_TOKEN, or CHALLENGE_SCOUTING for local runs."
    )

// Turns the rendered document into compact text for the model. Every element the model can act on gets a
// reference (`data-aid`) and appears inline as `[ref kind: label]`, so labels are not repeated in a second list.
(prefix) => {
  const SKIP = new Set(["SCRIPT", "STYLE", "NOSCRIPT", "TEMPLATE", "SVG", "HEAD"]);
  const BLOCK = new Set([
    "ADDRESS", "ARTICLE", "ASIDE", "BLOCKQUOTE", "CAPTION", "DD", "DETAILS", "DIALOG", "DIV", "DL", "DT",
    "FIELDSET", "FIGCAPTION", "FIGURE", "FOOTER", "FORM", "H1", "H2", "H3", "H4", "H5", "H6", "HEADER", "LI",
    "MAIN", "NAV", "OL", "P", "PRE", "SECTION", "SUMMARY", "TABLE", "TR", "UL",
  ]);
  const CLICKABLE =
    "a[href], button, summary, [role=button], [role=link], [role=tab], [role=menuitem], [role=option], " +
    "[role=checkbox], [role=radio], [role=switch]";
  const GENERIC_CLICKABLE = '[onclick], [tabindex]:not([tabindex="-1"])';

  const lines = [];
  let line = "";
  let count = 0;

  const flush = () => {
    const text = line.replace(/\s+/g, " ").trim();
    if (text) lines.push(text);
    line = "";
  };
  const clean = (value, limit) => (value || "").replace(/\s+/g, " ").trim().slice(0, limit);
  const mark = (el) => {
    const ref = prefix + count++;
    el.setAttribute("data-aid", ref);
    return ref;
  };
  const attrs = (el, names) =>
    names
      .map((name) => {
        const value = clean(el.getAttribute(name), 60);
        return value ? ` ${name}="${value}"` : "";
      })
      .join("");
  const disabled = (el) => (el.disabled || el.getAttribute("aria-disabled") === "true" ? " disabled" : "");
  const label = (el) =>
    clean(el.innerText, 120) ||
    clean(el.getAttribute("aria-label"), 120) ||
    clean(el.getAttribute("title"), 120) ||
    clean(el.value, 120) ||
    clean(el.querySelector("img[alt]")?.getAttribute("alt"), 120);
  const pointer = (el) => getComputedStyle(el).cursor === "pointer";
  const clearRefs = (root) => root.querySelectorAll("[data-aid]").forEach((el) => el.removeAttribute("data-aid"));

  const walk = (node) => {
    if (node.nodeType === Node.TEXT_NODE) {
      line += node.textContent;
      return;
    }
    if (node.nodeType !== Node.ELEMENT_NODE) return;
    const el = node;
    const tag = el.tagName.toUpperCase();
    if (SKIP.has(tag)) return;
    if (!el.checkVisibility({ visibilityProperty: true })) return;

    const block = BLOCK.has(tag);
    if (block) flush();

    if (tag === "BR") {
      flush();
      return;
    }
    if (tag === "IMG") {
      const alt = clean(el.getAttribute("alt"), 80);
      if (alt) line += ` [image: ${alt}] `;
      return;
    }
    if (tag === "IFRAME" || tag === "FRAME") {
      line += ` [embedded frame${attrs(el, ["title", "name"])}: its content is listed in its own section] `;
      return;
    }
    if (tag === "INPUT") {
      const type = (el.getAttribute("type") || "text").toLowerCase();
      if (type === "hidden") return;
      const ref = mark(el);
      if (["submit", "button", "reset", "image"].includes(type)) {
        line += ` [${ref} button: ${label(el)}${disabled(el)}] `;
        return;
      }
      let state = "";
      if (type === "checkbox" || type === "radio") state = el.checked ? " checked" : "";
      else if (type === "password") state = el.value ? ' value="(hidden)"' : "";
      else if (el.value) state = ` value="${clean(el.value, 80)}"`;
      line += ` [${ref} input:${type}${attrs(el, ["name", "placeholder", "aria-label"])}${state}${disabled(el)}] `;
      return;
    }
    if (tag === "TEXTAREA") {
      const value = el.value ? ` value="${clean(el.value, 200)}"` : "";
      line += ` [${mark(el)} textarea${attrs(el, ["name", "placeholder", "aria-label"])}${value}${disabled(el)}] `;
      return;
    }
    if (tag === "SELECT") {
      const options = [...el.options].slice(0, 40).map((option) => clean(option.text, 60));
      const selected = clean(el.selectedOptions[0]?.text, 60);
      line +=
        ` [${mark(el)} select${attrs(el, ["name", "aria-label"])} selected="${selected}"` +
        ` options="${options.join(" | ")}"${disabled(el)}] `;
      return;
    }
    if (el.matches(CLICKABLE)) {
      const kind = tag === "A" ? "link" : el.getAttribute("role") || tag.toLowerCase();
      line += ` [${mark(el)} ${kind}: ${label(el)}${disabled(el)}] `;
      if (block) flush();
      return;
    }
    // Containers that react to clicks keep their content readable, with a reference in front of it.
    const parent = el.parentElement;
    if (el.matches(GENERIC_CLICKABLE) || (pointer(el) && !(parent && pointer(parent)))) {
      line += ` [${mark(el)} clickable] `;
    }

    if (/^H[1-6]$/.test(tag)) line += "#".repeat(Number(tag[1])) + " ";
    if (tag === "LI") line += "- ";
    if (el.shadowRoot) {
      clearRefs(el.shadowRoot);
      for (const child of el.shadowRoot.childNodes) walk(child);
    }
    for (const child of el.childNodes) walk(child);
    if (tag === "TD" || tag === "TH") line += " | ";
    if (block) flush();
  };

  if (!document.body) return "";
  clearRefs(document);
  walk(document.body);
  flush();
  return lines.join("\n");
}

"""Generic browser tools a model drives one web application with.

Nothing here knows a particular site. The model reads a page as text in which every element it can act on
carries a reference, and names that reference in the next tool call.
"""

from __future__ import annotations

import asyncio
import json
import re
from pathlib import Path
from typing import Any

from playwright.async_api import Dialog, Error, Frame, Locator, Page
from playwright.async_api import TimeoutError as PlaywrightTimeout

SNAPSHOT_JS = (Path(__file__).parent / "snapshot.js").read_text(encoding="utf-8")

# Characters of page text returned per tool result; `observe` with an offset pages through the rest.
PAGE_CHARS = 6000
ACTION_TIMEOUT_MS = 8000
LOAD_TIMEOUT_MS = 15000
IDLE_TIMEOUT_MS = 2500

_REF = re.compile(r"(f\d+)e\d+")


def _tool(name: str, description: str, properties: dict[str, Any], required: list[str]) -> dict[str, Any]:
    return {
        "type": "function",
        "function": {
            "name": name,
            "description": description,
            "parameters": {"type": "object", "properties": properties, "required": required},
        },
    }


_REF_PARAM = {"type": "string", "description": "Element reference from the latest page text, e.g. f0e12"}

TOOL_SPECS: list[dict[str, Any]] = [
    _tool(
        "observe",
        "Read the current page as text. Elements you can act on appear as [ref kind: label]. "
        "Long pages come in parts: pass the offset named at the end of a part to read the next one.",
        {"offset": {"type": "integer", "description": "Character offset to continue from; 0 re-reads the page"}},
        [],
    ),
    _tool("click", "Click an element.", {"ref": _REF_PARAM}, ["ref"]),
    _tool(
        "type_text",
        "Replace the content of an input or textarea with the given text.",
        {
            "ref": _REF_PARAM,
            "text": {"type": "string"},
            "press_enter": {"type": "boolean", "description": "Press Enter afterwards, e.g. to run a search"},
        },
        ["ref", "text"],
    ),
    _tool(
        "fill_credential",
        "Fill this application's own login name or password into an input. The value is inserted for you.",
        {"ref": _REF_PARAM, "field": {"type": "string", "enum": ["username", "password"]}},
        ["ref", "field"],
    ),
    _tool(
        "select_option",
        "Choose an option of a select element by its visible text.",
        {"ref": _REF_PARAM, "option": {"type": "string"}},
        ["ref", "option"],
    ),
    _tool(
        "press_key",
        "Press a key on the page, e.g. Enter, Escape, F4, PageDown.",
        {"key": {"type": "string"}},
        ["key"],
    ),
    _tool("open_url", "Navigate the current tab to a URL of this application.", {"url": {"type": "string"}}, ["url"]),
    _tool("go_back", "Go back one step in the tab's history.", {}, []),
    _tool("close_tab", "Close a tab that an earlier action opened and return to the tab before it.", {}, []),
]


class BrowserTools:
    """The tools of one worker, bound to one tab (and to the tabs that tab opens)."""

    def __init__(self, page: Page, credentials: dict[str, str]) -> None:
        self._pages: list[Page] = []
        self._credentials = credentials
        self._frames: dict[str, Frame] = {}
        self._text = ""
        self._notices: list[str] = []
        self._adopt(page)

    @property
    def page(self) -> Page:
        return self._pages[-1]

    def _adopt(self, page: Page) -> None:
        self._pages.append(page)
        page.on("popup", self._on_popup)
        page.on("dialog", lambda dialog: asyncio.ensure_future(self._on_dialog(dialog)))

    def _on_popup(self, page: Page) -> None:
        self._notices.append("The last action opened a new tab; you are now on it. Use close_tab to return.")
        self._adopt(page)

    async def _on_dialog(self, dialog: Dialog) -> None:
        self._notices.append(f"A {dialog.type} dialog appeared and was accepted: {dialog.message}")
        try:
            await dialog.accept()
        except Error:
            pass

    async def call(self, name: str, arguments: dict[str, Any]) -> str:
        """Run one tool call and return what the model reads next. Failures come back as text, not exceptions."""
        handler = getattr(self, f"_tool_{name}", None)
        if handler is None:
            return f"Unknown tool: {name}"
        try:
            return await handler(**arguments)
        except PlaywrightTimeout:
            return "The action timed out. The page may have changed; observe it again.\n\n" + await self._observe()
        except (Error, TypeError, ValueError) as error:
            return f"The action failed: {str(error).splitlines()[0]}\n\n" + await self._observe()

    # --- reading ---------------------------------------------------------------------------------------------

    async def _snapshot(self) -> None:
        self._frames = {}
        parts: list[str] = []
        for index, frame in enumerate(self.page.frames):
            prefix = f"f{index}"
            try:
                text = await frame.evaluate(SNAPSHOT_JS, f"{prefix}e")
            except Error:
                continue
            self._frames[prefix] = frame
            if frame is self.page.main_frame:
                parts.append(text)
            elif text:
                parts.append(f"--- embedded frame {prefix} ({frame.url}) ---\n{text}")
        self._text = "\n".join(parts)

    async def _observe(self, offset: int = 0) -> str:
        if offset == 0:
            await self._settle()
            await self._snapshot()
        header = ""
        if offset == 0:
            header = f"URL: {self.page.url}\nTitle: {await self.page.title()}\n"
            if len(self._pages) > 1:
                header += f"Open tabs: {len(self._pages)} (this is the newest)\n"
            if self._notices:
                header += "".join(f"Note: {notice}\n" for notice in self._notices)
                self._notices = []
            header += "\n"
        end = offset + PAGE_CHARS
        body = self._text[offset:end]
        if end < len(self._text):
            body += f"\n\n[The page continues: {len(self._text) - end} more characters. observe(offset={end})]"
        return header + (body or "(no visible text)")

    async def _settle(self) -> None:
        # A click may open a tab or start a navigation a moment later.
        await asyncio.sleep(0.25)
        try:
            await self.page.wait_for_load_state("domcontentloaded", timeout=LOAD_TIMEOUT_MS)
            await self.page.wait_for_load_state("networkidle", timeout=IDLE_TIMEOUT_MS)
        except (PlaywrightTimeout, Error):
            pass

    def _locate(self, ref: str) -> Locator:
        match = _REF.fullmatch(ref)
        frame = self._frames.get(match.group(1)) if match else None
        if frame is None:
            raise ValueError(f"No element {ref!r} in the latest page text")
        return frame.locator(f'[data-aid="{ref}"]')

    # --- tools -----------------------------------------------------------------------------------------------

    async def _tool_observe(self, offset: int = 0) -> str:
        return await self._observe(max(0, int(offset)))

    async def _tool_click(self, ref: str) -> str:
        target = self._locate(ref)
        try:
            await target.click(timeout=ACTION_TIMEOUT_MS)
        except PlaywrightTimeout:
            # Covered or animating elements: fire the click on the element itself.
            await target.dispatch_event("click", timeout=ACTION_TIMEOUT_MS)
        return await self._observe()

    async def _tool_type_text(self, ref: str, text: str, press_enter: bool = False) -> str:
        target = self._locate(ref)
        await target.fill(text, timeout=ACTION_TIMEOUT_MS)
        if press_enter:
            await target.press("Enter", timeout=ACTION_TIMEOUT_MS)
        return await self._observe()

    async def _tool_fill_credential(self, ref: str, field: str) -> str:
        if field not in self._credentials:
            raise ValueError(f"Unknown credential field {field!r}")
        await self._locate(ref).fill(self._credentials[field], timeout=ACTION_TIMEOUT_MS)
        return await self._observe()

    async def _tool_select_option(self, ref: str, option: str) -> str:
        target = self._locate(ref)
        try:
            await target.select_option(label=option, timeout=ACTION_TIMEOUT_MS)
        except (PlaywrightTimeout, Error):
            await target.select_option(value=option, timeout=ACTION_TIMEOUT_MS)
        return await self._observe()

    async def _tool_press_key(self, key: str) -> str:
        await self.page.keyboard.press(key)
        return await self._observe()

    async def _tool_open_url(self, url: str) -> str:
        if not url.startswith(("http://", "https://")):
            raise ValueError("open_url needs an absolute http(s) URL")
        await self.page.goto(url, wait_until="domcontentloaded", timeout=LOAD_TIMEOUT_MS * 2)
        return await self._observe()

    async def _tool_go_back(self) -> str:
        await self.page.go_back(wait_until="domcontentloaded", timeout=LOAD_TIMEOUT_MS)
        return await self._observe()

    async def _tool_close_tab(self) -> str:
        if len(self._pages) == 1:
            return "This is the only tab.\n\n" + await self._observe()
        await self._pages.pop().close()
        return await self._observe()


def parse_arguments(raw: str | None) -> dict[str, Any]:
    """Arguments of a model's tool call; an unreadable payload becomes an empty call the tool can reject."""
    try:
        value = json.loads(raw or "{}")
    except json.JSONDecodeError:
        return {}
    return value if isinstance(value, dict) else {}

