# Structure only. Report text is printed with every digit masked, so no value from the websites is shown.
pat = re.compile(r"^\[\s*([\d.]+)s\]\s+\[([A-Za-z0-9_-]+)\]\s+(<- )?([A-Za-z_]+)")
short = {"goto": "g", "look": "l", "type": "t", "click": "c", "select": "s", "read_more": "r", "press": "p",
         "back": "b", "download": "d", "read_file": "f", "login": "L", "note": "n", "finished": "F", "stopped": "X"}
for path in sys.argv[1:]:
    lines = open(path, errors="replace").read().splitlines()
    print("=" * 70); print(path.split("/")[-1])
    seq = {}
    for l in lines:
        m = pat.match(l)
        if m and m.group(4) in short:
            seq.setdefault(m.group(2), []).append((float(m.group(1)), short[m.group(4)]))
    for who, items in seq.items():
        gaps = sorted(((b[0] - a[0], a[0]) for a, b in zip(items, items[1:])), reverse=True)[:2]
        print(f"{who:16} {items[0][0]:6.0f}-{items[-1][0]:6.0f}s  n={len(items):3}  {''.join(x for _, x in items)}")
        print(f"{'':16} longest waits: " + ", ".join(f"{g:.0f}s at {t:.0f}s" for g, t in gaps))
    # the submit sub-agent's own report, digits masked
    for i, l in enumerate(lines):
        if re.match(r"^\[\s*[\d.]+s\]\s+\[lead\] <- submit_bid", l):
            block = [l] + [x for x in lines[i + 1:i + 40] if not re.match(r"^\[\s*[\d.]+s\]", x)]
            text = re.sub(r"\d", "#", "\n".join(block))[:1500]
            print("--- submit report (digits masked):"); print(text)
            break
