1	// Renders one frame's DOM as compact text for the model. Interactive elements get a number in brackets,
2	// stamped on the element as data-aid so an action can find it again. Tables become " | " rows.
3	// Called with {prefix, start, full}; returns {text, next}.
4	({prefix, start, full}) => {
5	  let n = start;
6	  const lines = [];
7	  const SKIP = new Set(["SCRIPT", "STYLE", "NOSCRIPT", "TEMPLATE", "SVG", "HEAD", "META", "LINK"]);
8	  const BLOCK = new Set(["DIV", "P", "SECTION", "ARTICLE", "MAIN", "HEADER", "FOOTER", "NAV", "ASIDE", "UL", "OL",
9	    "LI", "H1", "H2", "H3", "H4", "H5", "H6", "FORM", "FIELDSET", "LEGEND", "TR", "DL", "DT", "DD", "PRE", "BLOCKQUOTE",
10	    "DETAILS", "SUMMARY", "BR", "HR", "TABLE", "CAPTION", "FIGURE", "FIGCAPTION", "LABEL", "DIALOG"]);
11	  const clean = (s) => (s || "").replace(/[​-‏⁠﻿­]/g, "").replace(/\s+/g, " ").trim();
12	  // text the eye would get from hovering: a hidden tooltip, or a title/aria-label on a plain element
13	  const hint = (el) => {
14	    const parts = [];
15	    const own = clean(el.innerText || "") + " " + clean(el.textContent || "");
16	    for (const a of ["aria-label", "title", "data-tooltip", "datetime"]) {
17	      const v = clean(el.getAttribute(a));
18	      if (v && !own.includes(v) && !parts.includes(v)) parts.push(v);
19	    }
20	    const ref = referenced(el);
21	    if (ref) parts.push(ref);
22	    return parts.length ? ` (${parts.join("; ")})` : "";
23	  };
24	  // text of elements this one points to (tooltips, descriptions), even when they are hidden until hover
25	  const shownRefs = new Set();
26	  function referenced(el) {
27	    const out = [];
28	    for (const a of ["aria-describedby", "aria-labelledby", "aria-details"]) {
29	      for (const id of (el.getAttribute(a) || "").split(/\s+/).filter(Boolean)) {
30	        const target = document.getElementById(id);
31	        if (target && !target.contains(el) && !shownRefs.has(target)) {
32	          shownRefs.add(target);
33	          const v = clean(target.textContent);
34	          if (v) out.push(`tooltip: ${v}`);
35	        }
36	      }
37	    }
38	    return out.join("; ");
39	  }
40	
41	  const hidden = (el) => {
42	    if (el.hidden || el.getAttribute("aria-hidden") === "true") return true;
43	    const cs = getComputedStyle(el);
44	    if (cs.display === "none") return true;
45	    if (cs.visibility === "hidden" && el.tagName !== "DETAILS") return true;
46	    return false;
47	  };
48	  const interactive = (el) => {
49	    const t = el.tagName;
50	    if (t === "A" && el.hasAttribute("href")) return true;
51	    if (["BUTTON", "SELECT", "TEXTAREA", "SUMMARY"].includes(t)) return true;
52	    if (t === "INPUT") return el.type !== "hidden";
53	    const role = el.getAttribute("role");
54	    if (["button", "link", "tab", "menuitem", "checkbox", "radio", "option", "switch"].includes(role)) return true;
55	    if (el.hasAttribute("onclick") || el.hasAttribute("data-action")) return true;
56	    return false;
57	  };
58	  const tag = (el) => {
59	    const id = `${prefix}${n++}`;
60	    el.setAttribute("data-aid", id);
61	    return id;
62	  };
63	  const describe = (el) => {
64	    const t = el.tagName;
65	    const id = tag(el);
66	    const extra = [];
67	    const title = el.getAttribute("title"), aria = el.getAttribute("aria-label");
68	    if (aria) extra.push(`aria="${clean(aria)}"`);
69	    if (title && title !== aria) extra.push(`title="${clean(title)}"`);
70	    if (el.disabled) extra.push("disabled");
71	    const ref = referenced(el);
72	    if (ref) extra.push(`(${ref})`);
73	    if (t === "A") {
74	      const href = el.getAttribute("href") || "";
75	      const dl = el.hasAttribute("download") ? " download" : "";
76	      return `[${id}] link "${clean(el.innerText)}"${extra.length ? " " + extra.join(" ") : ""} -> ${href.slice(0, 160)}${dl}`;
77	    }
78	    if (t === "INPUT") {
79	      const type = el.type || "text";
80	      const lbl = el.labels && el.labels[0] ? clean(el.labels[0].innerText) : "";
81	      if (type === "checkbox" || type === "radio")
82	        return `[${id}] ${type} name=${el.name} value="${el.value}" ${el.checked ? "CHECKED" : "unchecked"}${lbl ? ` label="${lbl}"` : ""} ${extra.join(" ")}`;
83	      if (type === "submit" || type === "button") return `[${id}] button "${el.value}" ${extra.join(" ")}`;
84	      if (type === "file") return `[${id}] file-input name=${el.name}`;
85	      const ph = el.placeholder ? ` placeholder="${el.placeholder}"` : "";
86	      return `[${id}] input(${type}) name=${el.name}${lbl ? ` label="${lbl}"` : ""}${ph} value="${el.value}"${el.readOnly ? " readonly" : ""} ${extra.join(" ")}`;
87	    }
88	    if (t === "TEXTAREA") return `[${id}] textarea name=${el.name} value="${clean(el.value).slice(0, 300)}"`;
89	    if (t === "SELECT") {
90	      const opts = [...el.options].map((o) => `${o.selected ? "*" : ""}${clean(o.text)}${o.value !== o.text ? `(${o.value})` : ""}`);
91	      return `[${id}] select name=${el.name} options: ${opts.join(" ; ").slice(0, 1500)}`;
92	    }
93	    if (t === "SUMMARY") return `[${id}] summary "${clean(el.innerText)}" (${el.parentElement.open ? "open" : "closed"})`;
94	    return `[${id}] ${t === "BUTTON" ? "button" : (el.getAttribute("role") || "clickable")} "${clean(el.innerText || el.value)}" ${extra.join(" ")}`;
95	  };
96	
97	  // inline text of a node, with interactive descendants inlined as [id] markers
98	  const inline = (node, out) => {
99	    for (const c of node.childNodes) {
100	      if (c.nodeType === 3) { out.push(c.textContent); continue; }
101	      if (c.nodeType !== 1 || SKIP.has(c.tagName)) continue;
102	      if (hidden(c)) {
103	        if (c.getAttribute("role") === "tooltip") out.push(` (tooltip: ${clean(c.textContent)}) `);
104	        continue;
105	      }
106	      if (c.tagName === "IFRAME") { out.push(" [iframe] "); continue; }
107	      if (interactive(c)) { out.push(` ${describe(c)} `); continue; }
108	      inline(c, out);
109	      const h = hint(c);
110	      if (h) out.push(h);
111	    }
112	    return out;
113	  };
114	
115	  const walk = (el, depth) => {
116	    if (el.nodeType === 3) { const s = clean(el.textContent); if (s) lines.push(s); return; }
117	    if (el.nodeType !== 1 || SKIP.has(el.tagName)) return;
118	    if (hidden(el)) {
119	      // tooltips and collapsed hints often carry data; keep their text, flagged
120	      const role = el.getAttribute("role");
121	      if (role === "tooltip" || el.tagName === "DETAILS") { const s = clean(el.textContent); if (s) lines.push(`(hidden ${role || "details"}: ${s.slice(0, 600)})`); }
122	      return;
123	    }
124	    const t = el.tagName;
125	    if (t === "IFRAME") { lines.push(`[iframe name="${el.name || ""}" src="${(el.getAttribute("src") || "").slice(0, 120)}" — its content follows as a separate frame]`); return; }
126	    if (t === "CANVAS") { const s = el.getAttribute("aria-label") || el.getAttribute("title") || ""; lines.push(`[canvas${s ? ": " + clean(s) : ""}]`); return; }
127	    if (t === "IMG") { const a = el.getAttribute("alt") || el.getAttribute("title"); if (a) lines.push(`[image: ${clean(a)}]`); return; }
128	    if (t === "TABLE") {
129	      const cap = el.querySelector(":scope > caption");
130	      if (cap) lines.push(`## ${clean(cap.innerText)}`);
131	      lines.push("<table>");
132	      for (const row of el.rows) {
133	        if (hidden(row)) continue;
134	        const cells = [...row.cells].map((c) => clean(inline(c, []).join(" ")));
135	        lines.push("| " + cells.join(" | ") + " |");
136	      }
137	      lines.push("</table>");
138	      return;
139	    }
140	    if (interactive(el)) {
141	      // a link/button that wraps block content: show its own text inline
142	      lines.push(describe(el));
143	      return;
144	    }
145	    if (t === "DT" && el.nextElementSibling && el.nextElementSibling.tagName === "DD") {
146	      lines.push(`${clean(inline(el, []).join(" "))}: ${clean(inline(el.nextElementSibling, []).join(" "))}`);
147	      el.nextElementSibling.setAttribute("data-agent-done", "1");
148	      return;
149	    }
150	    if (el.getAttribute("data-agent-done")) { el.removeAttribute("data-agent-done"); return; }
151	    const hasBlockChild = [...el.children].some((c) => BLOCK.has(c.tagName) || c.tagName === "TABLE" || c.tagName === "IFRAME" || c.tagName === "CANVAS");
152	    if (!hasBlockChild) {
153	      const s = clean(inline(el, []).join(" "));
154	      if (s) lines.push(/^H[1-6]$/.test(t) ? `${"#".repeat(+t[1])} ${s}` : s);
155	      return;
156	    }
157	    for (const c of el.childNodes) walk(c, depth + 1);
158	  };
159	
160	  document.querySelectorAll("[data-aid]").forEach((e) => e.removeAttribute("data-aid"));
161	  if (document.body) walk(document.body, 0);
162	  // collapse duplicate consecutive lines
163	  const out = [];
164	  for (const l of lines) if (out[out.length - 1] !== l) out.push(l);
165	  return {text: out.join("\n"), next: n, title: document.title};
166	}
